// Data Engineer Professional track: second part of the question bank (180 questions).
// Together with content-professional-quiz.js there are 300 questions, split across the nine exam
// sections in proportion to their weights, enough for five mock exams with no repeated questions.

window.TRAINER = window.TRAINER || {};

const PQ2 = (id, domain, q, options, answer, explain, code) =>
  Object.assign({ id, domain, q, options, answer, explain }, code ? { code } : {});

